export function createLedger({ expectedAmounts = {} } = {}) {
  const records = new Map();
  const handledIds = new Set();

  const knownTypes = new Set([
    "charge.success",
    "charge.failed",
    "charge.abandoned",
    "refund.processed",
  ]);

  const terminalChargeStatuses = new Set([
    "success",
    "partially_refunded",
    "refunded",
    "amount_mismatch",
  ]);

  function hasExpectedAmount(reference) {
    return Object.prototype.hasOwnProperty.call(expectedAmounts, reference);
  }

  function applyRefund(state, amountKobo) {
    if (state.status === "refunded") {
      return false;
    }

    const total = state.refundedKobo + amountKobo;
    if (total > state.amountKobo) {
      return false;
    }

    state.refundedKobo = total;
    state.status =
      total === state.amountKobo ? "refunded" : "partially_refunded";
    return true;
  }

  return {
    handle(event) {
      const type = event && event.type;
      if (!event || !knownTypes.has(type)) {
        return { applied: false, reason: "unknown-type", status: null };
      }

      const { id, reference, amountKobo } = event;
      let state = records.get(reference);

      if (handledIds.has(id)) {
        return {
          applied: false,
          reason: "duplicate",
          status: state ? state.status : null,
        };
      }

      if (
        (type === "charge.success" || type === "refund.processed") &&
        (!Number.isInteger(amountKobo) || amountKobo <= 0)
      ) {
        return {
          applied: false,
          reason: "invalid-amount",
          status: state ? state.status : null,
        };
      }

      handledIds.add(id);

      if (!state) {
        state = {
          reference,
          status: "pending",
          amountKobo: hasExpectedAmount(reference)
            ? expectedAmounts[reference]
            : null,
          refundedKobo: 0,
          deferredRefunds: [],
        };
        records.set(reference, state);
      }

      if (type === "refund.processed") {
        if (state.status === "amount_mismatch") {
          return {
            applied: false,
            reason: "terminal",
            status: state.status,
          };
        }

        if (
          state.status === "success" ||
          state.status === "partially_refunded" ||
          state.status === "refunded"
        ) {
          const applied = applyRefund(state, amountKobo);
          return {
            applied,
            reason: applied ? null : "over-refund",
            status: state.status,
          };
        }

        state.deferredRefunds.push(amountKobo);
        return {
          applied: false,
          reason: "deferred",
          status: state.status,
        };
      }

      if (terminalChargeStatuses.has(state.status)) {
        return {
          applied: false,
          reason: "terminal",
          status: state.status,
        };
      }

      if (type === "charge.failed") {
        if (state.status === "failed") {
          return { applied: false, reason: "stale", status: state.status };
        }

        state.status = "failed";
        return { applied: true, reason: null, status: state.status };
      }

      if (type === "charge.abandoned") {
        if (state.status !== "pending") {
          return { applied: false, reason: "stale", status: state.status };
        }

        state.status = "abandoned";
        return { applied: true, reason: null, status: state.status };
      }

      const hasExpected = hasExpectedAmount(reference);
      const expectedAmount = hasExpected ? expectedAmounts[reference] : null;

      if (hasExpected && amountKobo !== expectedAmount) {
        state.status = "amount_mismatch";
        state.deferredRefunds.length = 0;
        return {
          applied: true,
          reason: "amount-mismatch",
          status: state.status,
        };
      }

      state.amountKobo = hasExpected ? expectedAmount : amountKobo;
      state.status = "success";

      for (const refundAmount of state.deferredRefunds) {
        applyRefund(state, refundAmount);
      }
      state.deferredRefunds.length = 0;

      return { applied: true, reason: null, status: state.status };
    },

    get(reference) {
      const state = records.get(reference);
      if (!state) {
        return undefined;
      }

      return {
        reference: state.reference,
        status: state.status,
        amountKobo: state.amountKobo,
        refundedKobo: state.refundedKobo,
      };
    },
  };
}
